def shortestPalindrome(s):
    if len(s) == 0:
        return ""

    def is_palindrome(sub):
        return sub == sub[::-1]

    for i in range(len(s)):
        if is_palindrome(s[:len(s) - i]):
            return s[len(s) - i:][::-1] + s
    return s[::-1] + s

# Example 1
